arguments.command:
kubectl --server=https://host.docker.internal:16443 --token=Q9z20TQ7Nko-y3Da3yngoUnHVNl-9TAO2Fgr2ZNpf9s --insecure-skip-tls-verify patch configmap coredns -n kube-system --type merge -p '{"data":{"Corefile":":53 {
    errors
    health {
       lameduck 5s
    }
    ready
    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
       ttl 30
    }
    prometheus :9153
    forward . /etc/resolv.conf {
       max_concurrent 1000
    }
    cache 30 {
       disable success cluster.local
       disable denial cluster.local
    }
    loop
    reload
    loadbalance
}"}}' 2>&1

